import itertools

def solve_for_sequence(a):
    n = len(a)
    dp_max = [0] * n
    dp_min = [0] * n

    for i in range(n):
        # dp_max[i] is the max sum of a sequence ending at i
        prev_max = 0
        if i > 0:
            prev_max = max(prev_max, dp_max[i-1])
        if i > 1:
            prev_max = max(prev_max, dp_max[i-2])
        dp_max[i] = a[i] + prev_max

        # dp_min[i] is the min sum of a sequence ending at i
        prev_min = 0
        if i > 0:
            prev_min = min(prev_min, dp_min[i-1])
        if i > 1:
            prev_min = min(prev_min, dp_min[i-2])
        dp_min[i] = a[i] + prev_min

    s_max = max(dp_max)
    s_min = min(dp_min)
    return max(abs(s_max), abs(s_min))

def find_c(n):
    min_max_abs_sum = float('inf')
    for a in itertools.product([1, -1], repeat=n):
        val = solve_for_sequence(a)
        if val < min_max_abs_sum:
            min_max_abs_sum = val
    return min_max_abs_sum

for n in range(1, 15):
    print(f"N={n}, C={find_c(n)}")

